<?php require_once __DIR__.'/auth.php';require_admin();require_once __DIR__.'/../includes/admin_layout.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$st=$pdo->prepare('UPDATE lab_orders SET status=?,result=?,completed_at=IF(?="Completed",NOW(),completed_at) WHERE id=?');$st->execute([$_POST['status'],trim($_POST['result']??''),$_POST['status'],$id]);audit('update','lab_order',$id,$_POST['status']);flash('Laboratory order updated.');redirect('laboratory.php');}if(($_GET['action']??'')==='new'&&$_SERVER['REQUEST_METHOD']!=='POST'){}$patients=$pdo->query('SELECT id,patient_no,full_name FROM patients ORDER BY full_name')->fetchAll();$staff=$pdo->query('SELECT id,full_name FROM staff WHERE active=1 ORDER BY full_name')->fetchAll();if(($_GET['action']??'')==='create'&&isset($_POST['create'])){}$rows=$pdo->query('SELECT l.*,p.patient_no,p.full_name,s.full_name requester FROM lab_orders l JOIN patients p ON p.id=l.patient_id LEFT JOIN staff s ON s.id=l.requested_by ORDER BY l.ordered_at DESC LIMIT 150')->fetchAll();admin_header('Laboratory','laboratory.php');?><div class="pagehead"><div><h1>Laboratory</h1><div class="muted">Request tests and record results.</div></div><a class="btn" href="?action=new">New lab order</a></div><?php if(($_GET['action']??'')==='new'):?><div class="card" style="margin-bottom:18px"><form method="post" action="../api/lab-order.php"><input type="hidden" name="redirect" value="../admin/laboratory.php"><?=csrf_field()?><div class="form-grid"><div class="field"><label>Patient</label><select name="patient_id" required><option value="">Select patient</option><?php foreach($patients as $p):?><option value="<?=$p['id']?>"><?=e($p['patient_no'].' — '.$p['full_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Requested by</label><select name="requested_by"><option value="">Select clinician</option><?php foreach($staff as $s):?><option value="<?=$s['id']?>"><?=e($s['full_name'])?></option><?php endforeach;?></select></div><div class="field full"><label>Test name</label><input name="test_name" required placeholder="e.g. Full Blood Count"></div></div><button style="margin-top:14px">Create order</button></form></div><?php endif;?><div class="card table-wrap"><table class="table"><tr><th>Date</th><th>Patient</th><th>Test</th><th>Requester</th><th>Status</th><th>Result / update</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['ordered_at'])?></td><td><?=e($r['patient_no'].' — '.$r['full_name'])?></td><td><?=e($r['test_name'])?></td><td><?=e($r['requester'])?></td><td><?=e($r['status'])?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option <?=($r['status']==='Requested'?'selected':'')?>>Requested</option><option <?=($r['status']==='Collected'?'selected':'')?>>Collected</option><option <?=($r['status']==='Completed'?'selected':'')?>>Completed</option><option <?=($r['status']==='Cancelled'?'selected':'')?>>Cancelled</option></select><textarea name="result" placeholder="Result"><?=e($r['result'])?></textarea><button style="margin-top:5px">Save</button></form></td></tr><?php endforeach;?></table></div><?php admin_footer();
